import math
import re

from config import STOPWORDS, EXPANSIONS, BROAD_TERMS

_WORD_RE = re.compile(r"[a-z0-9]+|[\u4e00-\u9fff]+")
_CLAUSE_SPLIT_RE = re.compile(r"[?？;；!！]|(?:\band\b)|(?:\bor\b)|(?:\bvs\.?\b)|,|、|，|以及|并且|还有|和")


def tokens(text):
    """Tokenize text into lowercase latin words and CJK character n-grams."""
    text = (text or "").lower()
    out = []
    for piece in _WORD_RE.findall(text):
        if piece[0] >= "\u4e00" and piece[0] <= "\u9fff":
            if len(piece) == 1:
                out.append(piece)
            else:
                out.extend(piece[i:i + 2] for i in range(len(piece) - 1))
                out.append(piece)
        else:
            out.append(piece)
    return out


def _normalize(term):
    return term.strip().lower()


def _query_terms(query):
    """Return ordered list of (term, weight) for the query after normalization."""
    raw = tokens(query)
    terms = []
    seen = set()

    def add(term, weight):
        term = _normalize(term)
        if not term or term in STOPWORDS:
            return
        if term in seen:
            return
        seen.add(term)
        terms.append((term, weight))

    for tok in raw:
        if tok in STOPWORDS:
            continue
        add(tok, 1.0)
        for exp in EXPANSIONS.get(tok, ()):
            for sub in tokens(exp):
                if sub not in STOPWORDS:
                    add(sub, 0.9)

    # Downweight broad parent terms when a specific (child) term is present.
    present = {t for t, _ in terms}
    adjusted = []
    for term, weight in terms:
        children = BROAD_TERMS.get(term)
        if children and (present & set(children)):
            weight *= 0.25
        adjusted.append((term, weight))
    return adjusted


def _split_clauses(query):
    parts = [p for p in _CLAUSE_SPLIT_RE.split(query or "") if p and p.strip()]
    return parts or [query or ""]


def _chunk_tokens(chunk):
    return set(tokens(chunk.get("text", "")))


def _idf_map(chunks):
    n = len(chunks)
    df = {}
    for c in chunks:
        for t in _chunk_tokens(c):
            df[t] = df.get(t, 0) + 1
    return {t: math.log((n + 1.0) / (d + 0.5)) + 1.0 for t, d in df.items()}


def _score(chunk, terms, idf, clause_terms):
    ctoks = _chunk_tokens(chunk)
    if not ctoks:
        return 0.0
    total_weight = sum(w for _, w in terms) or 1.0
    matched = 0.0
    for term, weight in terms:
        if term in ctoks:
            matched += weight * idf.get(term, 1.0)
    max_possible = sum(w * idf.get(t, 1.0) for t, w in terms) or 1.0
    coverage = matched / max_possible
    # Rarity-weighted coverage, mildly damped by chunk length so short
    # directory/title chunks do not always dominate.
    length_damp = 1.0 / (1.0 + 0.02 * math.log(1 + len(ctoks)))
    score = coverage * length_damp
    # Clause anchors: reward chunks covering distinct clauses.
    if clause_terms:
        covered = 0
        for cterms in clause_terms:
            if any(t in ctoks for t, _ in cterms):
                covered += 1
        score += 0.15 * (covered / len(clause_terms))
    return score


def _page_key(chunk):
    page = chunk.get("page")
    try:
        return int(page)
    except (TypeError, ValueError):
        return page


def search_context(chunks, query, top_k=3, neighbor_window=1, max_context=8):
    chunks = list(chunks or [])
    if not chunks:
        return []
    top_k = max(0, int(top_k))
    max_context = max(0, int(max_context))
    limit = min(top_k, max_context)
    if limit <= 0:
        return []

    terms = _query_terms(query)
    idf = _idf_map(chunks)
    clauses = _split_clauses(query)
    clause_terms = [_query_terms(c) for c in clauses]
    clause_terms = [c for c in clause_terms if c]

    scored = []
    for idx, c in enumerate(chunks):
        scored.append((_score(c, terms, idf, clause_terms), idx, c))
    scored.sort(key=lambda x: (-x[0], x[1]))

    selected = []
    selected_ids = set()

    def add(chunk, reason):
        key = chunk.get("id", id(chunk))
        if key in selected_ids:
            return False
        selected_ids.add(key)
        selected.append({**chunk, "retrieval_reason": reason})
        return True

    # Reserve one positive semantic anchor per clause.
    for cterms in clause_terms:
        if len(selected) >= limit:
            break
        best = None
        for score, idx, c in scored:
            if score <= 0:
                continue
            key = c.get("id", id(c))
            if key in selected_ids:
                continue
            ctoks = _chunk_tokens(c)
            if any(t in ctoks for t, _ in cterms):
                best = c
                break
        if best is not None:
            add(best, "semantic")

    # Fill remaining slots with top semantic matches.
    for score, idx, c in scored:
        if len(selected) >= limit:
            break
        if score <= 0:
            continue
        add(c, "semantic")

    # Add unique same-source neighboring pages.
    if neighbor_window and neighbor_window > 0 and len(selected) < max_context:
        by_source = {}
        for c in chunks:
            by_source.setdefault(c.get("source"), []).append(c)
        for c in list(selected):
            if len(selected) >= max_context:
                break
            page = _page_key(c)
            if not isinstance(page, int):
                continue
            source = c.get("source")
            for other in by_source.get(source, []):
                if len(selected) >= max_context:
                    break
                opage = _page_key(other)
                if not isinstance(opage, int):
                    continue
                if 0 < abs(opage - page) <= neighbor_window:
                    add(other, "neighbor")

    return selected[:max_context]
